def detect_potential_s3sigv4(func):
    def _wrapper(self):
        if os.environ.get('S3_USE_SIGV4', False):
            return ['hmac-v4-s3']

        if boto.config.get('s3', 'use-sigv4', False):
            return ['hmac-v4-s3']

        if not hasattr(self, 'host'):
            return func(self)

        # Keep the old explicit logic in case somebody was adding to the list.
        for test in SIGV4_DETECT:
            if test in self.host:
                return ['hmac-v4-s3']

        # Use default for non-aws hosts. Adding a url scheme is necessary if
        # not present for urlparse to properly function.
        host = self.host
        if not self.host.startswith('http://') or \
                self.host.startswith('https://'):
            host = 'https://' + host
        netloc = urlparse(host).netloc
        if not (netloc.endswith('amazonaws.com') or
                netloc.endswith('amazonaws.com.cn')):
            return func(self)

        # Use the default for the global endpoint
        if netloc.endswith('s3.amazonaws.com'):
            return func(self)

        # Use the default for regions that support sigv4 and sigv2
        if any(test in self.host for test in S3_AUTH_DETECT):
            return func(self)

        # Use anonymous if enabled.
        if hasattr(self, 'anon') and self.anon:
            return func(self)

        # Default to sigv4 for aws hosts outside of regions that are known
        # to support sigv2
        return ['hmac-v4-s3']
    return _wrapper

def generate_url(self, expires_in, method, bucket='', key='', headers=None,
                 query_auth=True, force_http=False, response_headers=None,
                 expires_in_absolute=False, version_id=None):
    if self._auth_handler.capability[0] == 'hmac-v4-s3' and query_auth:
        # Handle the special sigv4 case
        return self.generate_url_sigv4(expires_in, method, bucket=bucket,
            key=key, headers=headers, force_http=force_http,
            response_headers=response_headers, version_id=version_id)

    headers = headers or {}
    if expires_in_absolute:
        expires = int(expires_in)
    else:
        expires = int(time.time() + expires_in)
    auth_path = self.calling_format.build_auth_path(bucket, key)
    auth_path = self.get_path(auth_path)
    # optional version_id and response_headers need to be added to
    # the query param list.
    extra_qp = []
    if version_id is not None:
        extra_qp.append("versionId=%s" % version_id)
    if response_headers:
        for k, v in response_headers.items():
            extra_qp.append("%s=%s" % (k, urllib.parse.quote(v)))
    if self.provider.security_token:
        headers['x-amz-security-token'] = self.provider.security_token
    if extra_qp:
        delimiter = '?' if '?' not in auth_path else '&'
        auth_path += delimiter + '&'.join(extra_qp)
    self.calling_format.build_path_base(bucket, key)
    if query_auth and not self.anon:
        c_string = boto.utils.canonical_string(method, auth_path, headers,
                                               expires, self.provider)
        b64_hmac = self._auth_handler.sign_string(c_string)
        encoded_canonical = urllib.parse.quote(b64_hmac, safe='')
        query_part = '?' + self.QueryString % (encoded_canonical, expires,
                                               self.aws_access_key_id)
    else:
        query_part = ''
    if headers:
        hdr_prefix = self.provider.header_prefix
        for k, v in headers.items():
            if k.startswith(hdr_prefix):
                # headers used for sig generation must be
                # included in the url also.
                extra_qp.append("%s=%s" % (k, urllib.parse.quote(v)))
    if extra_qp:
        delimiter = '?' if not query_part else '&'
        query_part += delimiter + '&'.join(extra_qp)
    if force_http:
        protocol = 'http'
        port = 80
    else:
        protocol = self.protocol
        port = self.port
    return self.calling_format.build_url_base(self, protocol,
                                              self.server_name(port),
                                              bucket, key) + query_part
